247	func TestResolveEnvTokenCreds_TrustedAudSucceeds(t *testing.T) {
248		t.Parallel()
249		const core = "https://core.us.entire.io"
250		const audience = "https://us.entire.io"
251		srv, clusterHost := wellKnownServer(t, []string{core}, audience, core)
252	
253		creds, err := resolveEnvTokenCreds(
254			t.Context(), makeTestJWT(t, core), clusterHost, t.TempDir(), srv.Client(),
255		)
256		if err != nil {
257			t.Fatalf("expected trusted aud to succeed, got: %v", err)
258		}
259		if creds == nil {
260			t.Fatal("expected non-nil creds for trusted aud")
261		}
262		// The exchange must be pinned to the token's own (trust-gated) core with
263		// the cluster's advertised jurisdiction audience, and must never touch
264		// the keychain — CI runners don't have one.
265		if creds.fixedCoreURL != core {
266			t.Errorf("fixedCoreURL = %q, want %q", creds.fixedCoreURL, core)
267		}
268		if creds.audience != audience {
269			t.Errorf("audience = %q, want %q", creds.audience, audience)
270		}
271		if creds.persist {
272			t.Error("env-token creds must not persist to the keychain")
273		}
274		if creds.exchangeHint != "" {
275			t.Errorf("no cross-jurisdiction hint expected when the token's core is the jurisdiction core, got %q", creds.exchangeHint)
276		}
277	}
