341	func TestResolveCreds_BlankEnvTokenFailsClosed(t *testing.T) {
342		// If ENTIRE_TOKEN is set at all, presence commits us to the env-token path:
343		// an empty or whitespace-only value must fail closed with a clear message,
344		// never silently fall back to context auth. Sets a process-global env var,
